const response = $json.content.parts[0].text;

const data = JSON.parse(response);

return {
  json: data
};

const email = $json;

const normalize = (value) =>
  String(value || '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

const duplicate_key =
  normalize(email.sender) +
  '|' +
  normalize(email.subject) +
  '|' +
  normalize(email.body);

return [
  {
    json: {
      ...email,
      duplicate_key
    }
  }
];

const email = $json;

const sender =
  email.from?.value?.[0]?.address || '';

const senderName =
  email.from?.value?.[0]?.name || '';

const subject =
  email.subject || '';

const body =
  email.text || '';

const messageId =
  email.messageId || '';

return [
  {
    json: {
      message_id: messageId,
      sender,
      sender_name: senderName,
      subject: subject.trim(),
      body: body.trim(),
      received_at: email.date || null
    }
  }
];
